import itertools
import random

def max_bipartite_matching(graph):
    U = list(graph.keys())

    match = {}
    matching_size = 0

    def dfs(u, visited):
        for v in graph.get(u, []):
            if v not in visited:
                visited.add(v)
                if v not in match or dfs(match[v], visited):
                    match[v] = u
                    return True
        return False

    for u in U:
        visited = set()
        if dfs(u, visited):
            matching_size += 1

    return matching_size

def check_diversity(flags):
    if len(flags) != 8:
        return False

    flags_map = {i: flags[i] for i in range(8)}

    def check_color(color_C):
        graph = {}
        for i in range(8):
            graph[i] = []
            for j in range(8):
                if flags_map[i][j] == color_C:
                    graph[i].append(j)

        return max_bipartite_matching(graph) == 8

    return check_color(0) or check_color(1)

def generate_A64():
    flags = []
    for suffix_tuple in itertools.product([0, 1], repeat=6):
        flag = tuple([0, 0] + list(suffix_tuple))
        flags.append(flag)
    return flags

# Generate the set A64
A64 = generate_A64()
print(f"Size of A64: {len(A64)}")

# Test a random 8-subset from A64
random.seed(100) # Fix seed for reproducibility
random_sample_size = 8
random_subset = random.sample(A64, random_sample_size)
print(f"Diversity of a random 8-subset from A64: {check_diversity(random_subset)}")

